//! 🧳️ Original allocation progress owns its quote, callback and physical settlement independently of decoder orchestration.
use crate::{NativeAllocationRequest,NativeDecodeAllocationOutcome,ValueError,ValueRefusalKind};
use semio_framework_value_control_contract::NativeSendAllocationLoan;
fn commit_admission(ledger:&mut Option<semio_framework_value_receiving::NativeAllocationLedger>,request:NativeAllocationRequest)->Result<(),ValueError>{ledger.as_mut().ok_or_else(||ValueError::invariant("original allocation ledger absent"))?.commit(request)}
/// 🚦️ Records whether an original callback may already have taken effect.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeDecodeAllocationPhase{Absent,QuoteStarted,QuoteAccepted,QuoteRefused,SettlementStarted,Settled}
/// 🧭️ Keeps the original request and settlement boundary in the caller frame.
pub struct NativeDecodeAllocationProgress{request:NativeAllocationRequest,outcome:NativeDecodeAllocationOutcome,phase:NativeDecodeAllocationPhase,operation_started:bool,settled:bool,identity:Option<semio_framework_value_control_contract::NativeAllocationIdentity>,transaction:Option<semio_framework_value_control_contract::NativeAllocationTransaction>}
impl NativeDecodeAllocationProgress{
 /// 🪪️ Borrows the exact original request without exposing mutable authority.
 pub fn request(&self)->NativeAllocationRequest{self.request}
 /// 📊️ Borrows the retained outcome without modifying callback history.
 pub fn outcome(&self)->&NativeDecodeAllocationOutcome{&self.outcome}
 /// 🔍️ Reports whether the producer began its effect.
 pub fn operation_started(&self)->bool{self.operation_started}
 /// 🚦️ Observes the original callback boundary.
 pub fn phase(&self)->NativeDecodeAllocationPhase{self.phase}
 /// 🫴️ Transfers the outcome only after every original callback is settled.
 pub fn into_outcome(self)->Result<NativeDecodeAllocationOutcome,Self>{if self.pending(){Err(self)}else{let owner=std::mem::ManuallyDrop::new(self);Ok(unsafe{std::ptr::read(&owner.outcome)})}}
 /// ⏳️ Reports whether original callback custody remains unresolved.
 pub fn is_pending(&self)->bool{self.pending()}
}
impl NativeDecodeAllocationProgress{
 /// 🧭️ Reports whether an original callback still requires resolution.
 pub fn pending(&self)->bool{self.transaction.is_some()||(self.operation_started&&!self.settled)||matches!(self.phase,NativeDecodeAllocationPhase::QuoteStarted|NativeDecodeAllocationPhase::QuoteAccepted|NativeDecodeAllocationPhase::SettlementStarted)}}
impl Drop for NativeDecodeAllocationProgress{fn drop(&mut self){assert!(std::thread::panicking()||!self.pending(),"original allocation callback remains unsettled")}}
impl crate::retirement::RetireOwned for NativeDecodeAllocationProgress{
 type RetirementCursor=semio_framework_value_receiving::NativeRetirementGate<Self,<NativeDecodeAllocationOutcome as crate::retirement::RetireOwned>::RetirementCursor>;
 fn retirement_ready(&self)->bool{!self.pending()&&crate::retirement::RetireOwned::retirement_ready(&self.outcome)}
 fn retirement_seed(self)->Self::RetirementCursor{if !crate::retirement::RetireOwned::retirement_ready(&self){return semio_framework_value_receiving::NativeRetirementGate::Pending(self)}match self.into_outcome(){Ok(outcome)=>semio_framework_value_receiving::NativeRetirementGate::Ready(crate::retirement::RetireOwned::retirement_seed(outcome)),Err(original)=>semio_framework_value_receiving::NativeRetirementGate::Pending(original)}}
 fn retirement_birth_bytes(&self)->Option<usize>{crate::retirement::RetireOwned::retirement_ready(self).then_some(std::mem::size_of::<Self::RetirementCursor>())}
 fn controlled_retirement_supported()->bool{true}
}

pub enum NativeDecodeAllocationAdmission{Admitted,Refused(NativeDecodeAllocationOutcome),Pending}
fn allocation_refused(primary:ValueError)->NativeDecodeAllocationOutcome{NativeDecodeAllocationOutcome{request:None,admitted:false,primary:Some(primary),quote_refusal:None,extent_refusal:None,settlement_refusal:None,actual:None}}
fn settle_allocation_at(ledger:&mut Option<semio_framework_value_receiving::NativeAllocationLedger>,allocation:&mut NativeDecodeAllocationBinding<'_>,state:&mut NativeDecodeAllocationProgress,actual:Option<usize>)->Result<bool,ValueError>{let identity=match &mut *allocation{NativeDecodeAllocationBinding::Forwarded(port)=>Some(port.identity()),NativeDecodeAllocationBinding::Local=>None};if identity!=state.identity{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation progress requires its original authority"))}if matches!(state.phase,NativeDecodeAllocationPhase::QuoteStarted|NativeDecodeAllocationPhase::SettlementStarted){return Ok(false)}if state.settled{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation progress is already settled"))}if actual.is_some()&&!state.operation_started{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation cannot report an unperformed effect"))}if state.outcome.actual.is_some()&&state.outcome.actual!=actual{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"allocation actual differs from retained progress"))}state.outcome.actual=actual;if let Some(count)=actual{if !state.outcome.admitted{commit_admission(ledger,state.request)?;state.outcome.admitted=true}if count>state.request.bytes&&state.outcome.extent_refusal.is_none(){state.outcome.extent_refusal=Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"actual native allocation exceeds its quote"))}}if state.phase==NativeDecodeAllocationPhase::QuoteAccepted{if let NativeDecodeAllocationBinding::Forwarded(port)=allocation{if !settle_original_allocation(&mut **port,state,actual)?{return Ok(false)}}}state.settled=true;Ok(true)}
fn recover_original_allocation(port:&mut dyn NativeSendAllocationLoan,state:&mut NativeDecodeAllocationProgress)->Result<bool,ValueError>{let phase=state.phase;if phase==NativeDecodeAllocationPhase::QuoteRefused{port.finish(&mut state.transaction)?;return Ok(true)}if !matches!(phase,NativeDecodeAllocationPhase::QuoteStarted|NativeDecodeAllocationPhase::SettlementStarted){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation callback is not pending"))}let transaction=state.transaction.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation transaction is absent"))?;if phase==NativeDecodeAllocationPhase::SettlementStarted&&transaction.phase()==semio_framework_value_control_contract::NativeAllocationTransactionPhase::Settled{port.finish(&mut state.transaction)?;state.phase=NativeDecodeAllocationPhase::Settled;state.settled=true;return Ok(true)}if !port.recover(transaction)?{return Ok(false)}let verdict=transaction.take_verdict().expect("recovered original verdict");match phase{NativeDecodeAllocationPhase::QuoteStarted=>match verdict{Ok(())=>state.phase=NativeDecodeAllocationPhase::QuoteAccepted,Err(error)=>{state.phase=NativeDecodeAllocationPhase::QuoteRefused;state.outcome.quote_refusal=Some(error);port.finish(&mut state.transaction)?}},NativeDecodeAllocationPhase::SettlementStarted=>{state.outcome.settlement_refusal=verdict.err();port.finish(&mut state.transaction)?;state.phase=NativeDecodeAllocationPhase::Settled;state.settled=true},_=>unreachable!()}Ok(true)}
fn settle_original_allocation(port:&mut dyn NativeSendAllocationLoan,state:&mut NativeDecodeAllocationProgress,actual:Option<usize>)->Result<bool,ValueError>{let transaction=state.transaction.as_mut().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original allocation transaction is absent"))?;state.phase=NativeDecodeAllocationPhase::SettlementStarted;if let Err(error)=port.settle(transaction,actual){if transaction.phase()==semio_framework_value_control_contract::NativeAllocationTransactionPhase::QuoteAccepted{state.phase=NativeDecodeAllocationPhase::QuoteAccepted}return Err(error)}let Some(verdict)=transaction.take_verdict()else{return Ok(false)};state.outcome.settlement_refusal=verdict.err();port.finish(&mut state.transaction)?;state.phase=NativeDecodeAllocationPhase::Settled;state.settled=true;Ok(true)}

/// 🔗️ Borrows the actual original allocation authority or the local allocation path.
pub enum NativeDecodeAllocationBinding<'a>{Local,Forwarded(&'a mut(dyn NativeSendAllocationLoan+'a))}
impl NativeDecodeAllocationProgress{
 /// 🍼️ Publishes the original request and action before its allocation callback.
 pub fn begin(request:NativeAllocationRequest,allocation:&mut NativeDecodeAllocationBinding<'_>,progress:&mut Option<Self>)->NativeDecodeAllocationAdmission{if progress.is_some(){return NativeDecodeAllocationAdmission::Refused(allocation_refused(ValueError::invariant("original allocation progress is occupied")))}let identity=match &mut *allocation{NativeDecodeAllocationBinding::Forwarded(port)=>Some(port.identity()),NativeDecodeAllocationBinding::Local=>None};*progress=Some(NativeDecodeAllocationProgress{request,outcome:NativeDecodeAllocationOutcome{request:Some(request),admitted:false,primary:None,quote_refusal:None,extent_refusal:None,settlement_refusal:None,actual:None},phase:if identity.is_some(){NativeDecodeAllocationPhase::QuoteStarted}else{NativeDecodeAllocationPhase::Absent},operation_started:false,settled:false,identity,transaction:None});if let NativeDecodeAllocationBinding::Forwarded(port)=&mut *allocation{let state=progress.as_mut().unwrap();if let Err(error)=port.begin(request,true,&mut state.transaction){state.outcome.primary=Some(error);if state.transaction.is_some(){return NativeDecodeAllocationAdmission::Pending}state.phase=NativeDecodeAllocationPhase::QuoteRefused;return NativeDecodeAllocationAdmission::Refused(progress.take().unwrap().into_outcome().ok().expect("settled allocation outcome"))}let Some(result)=state.transaction.as_mut().expect("original quote transaction").take_verdict()else{return NativeDecodeAllocationAdmission::Pending};match result{Ok(())=>state.phase=NativeDecodeAllocationPhase::QuoteAccepted,Err(error)=>{state.phase=NativeDecodeAllocationPhase::QuoteRefused;state.outcome.quote_refusal=Some(error);if let Err(error)=port.finish(&mut state.transaction){state.outcome.primary=Some(error);return NativeDecodeAllocationAdmission::Pending}return NativeDecodeAllocationAdmission::Refused(progress.take().unwrap().into_outcome().ok().expect("settled allocation outcome"))}}}NativeDecodeAllocationAdmission::Admitted
 }
 /// ▶️ Records entry into the actual producer under the already accepted original quote.
 pub fn start_operation(&mut self)->Result<(),ValueError>{if self.settled||!matches!(self.phase,NativeDecodeAllocationPhase::Absent|NativeDecodeAllocationPhase::QuoteAccepted){return Err(ValueError::invariant("original allocation quote is not accepted"))}self.operation_started=true;Ok(())}
 /// 🧾️ Retains the actual marker before any later callback.
 pub fn record_actual(&mut self,actual:Option<usize>)->Result<(),ValueError>{if !self.operation_started||self.outcome.actual.is_some()&&self.outcome.actual!=actual{return Err(ValueError::invariant("original allocation marker changed"))}self.outcome.actual=actual;Ok(())}
 /// 🧳️ Retains an independent original operation refusal without replacing its prior cause.
 pub fn record_primary(&mut self,error:ValueError)->Result<(),ValueError>{if self.outcome.primary.is_some(){return Err(error)}self.outcome.primary=Some(error);Ok(())}
 /// 🔁️ Recovers only the same retained callback through its original allocation authority.
 pub fn recover(&mut self,allocation:&mut NativeDecodeAllocationBinding<'_>)->Result<bool,ValueError>{match allocation{NativeDecodeAllocationBinding::Forwarded(port)if Some(port.identity())==self.identity=>recover_original_allocation(&mut **port,self),_=>Err(ValueError::invariant("original allocation authority changed"))}}
 /// 🧾️ Settles the actual effect through the same original authority and ledger.
 pub fn settle(&mut self,ledger:&mut Option<semio_framework_value_receiving::NativeAllocationLedger>,allocation:&mut NativeDecodeAllocationBinding<'_>,actual:Option<usize>)->Result<bool,ValueError>{settle_allocation_at(ledger,allocation,self,actual)}
}

